update cat_profile
archive_no = #{archiveNo}, cat_name = #{catName}, alias = #{alias}, breed = #{breed}, sex = #{sex}, age_estimate = #{ageEstimate}, weight = #{weight}, personality = #{personality}, source = #{source}, capture_date = #{captureDate}, capture_point = #{capturePoint}, neutered = #{neutered}, dewormed = #{dewormed}, vaccinated = #{vaccinated}, feature = #{feature}, status = #{status}, base_id = #{baseId}, ward_id = #{wardId}, owner_base_id = #{ownerBaseId}, hospital_name = #{hospitalName}, qr_code = #{qrCode}, archived = #{archived}, update_by = #{updateBy}, update_time = sysdate()
where cat_id = #{catId}
